# recovery_table.R: parameter and policy recovery tables for S1. Reads the fits of every policy to data
# generated by every policy (simulations/recovery.sh) and the generating parameters (results/fits/).
suppressMessages({library(dplyr); library(readr); library(tidyr); library(here)})
pols <- c(simultaneous = "Simultaneous", sequential = "Best-first", commit = "Commit when certain")
grid <- expand_grid(gen = names(pols), fit = names(pols))
res <- bind_rows(lapply(seq_len(nrow(grid)), function(i) {
  f <- here(sprintf("results/recovery/fit_gen-%s_by-%s_stage2.csv", grid$gen[i], grid$fit[i])); if (!file.exists(f)) return(NULL)
  d <- read_csv(f, show_col_types = FALSE) %>% arrange(loss); top <- d %>% slice(1:10)
  tibble(gen = grid$gen[i], fit = grid$fit[i], loss = d$loss[1], sigma = mean(top$σ), sigma_sd = sd(top$σ),
         gs = mean(top$γs), gs_sd = sd(top$γs), gw = mean(top$γw), gw_sd = sd(top$γw))
}))
# policy recovery: loss of each fitted policy on each generating policy's data
lossm <- res %>% mutate(gen = pols[gen], fit = pols[fit]) %>% select(gen, fit, loss) %>% pivot_wider(names_from = fit, values_from = loss) %>%
  mutate(`Best-fitting policy` = names(pols)[max.col(-as.matrix(across(all_of(unname(pols)))))], `Best-fitting policy` = pols[`Best-fitting policy`])
write_csv(lossm, here("results/tables/recovery_loss.csv"))
cat("Policy recovery: loss of each fitted policy (columns) on data generated by each policy (rows)\n\n| Generating policy | ", paste(unname(pols), collapse = " | "), " | Best-fitting policy |\n|---|---|---|---|---|\n", sep = "")
for (i in seq_len(nrow(lossm))) cat(sprintf("| %s | %.1f | %.1f | %.1f | %s |\n", lossm$gen[i], lossm$Simultaneous[i], lossm$`Best-first`[i], lossm$`Commit when certain`[i], lossm$`Best-fitting policy`[i]))
# parameter recovery on the diagonal
gen_par <- bind_rows(lapply(names(pols), function(p) { d <- read_csv(here(sprintf("results/fits/fit_%s_stage2.csv", p)), show_col_types = FALSE) %>% arrange(loss) %>% slice(1); tibble(gen = p, g_sigma = d$σ, g_gs = d$γs, g_gw = d$γw) }))
diag <- res %>% filter(gen == fit) %>% inner_join(gen_par, by = "gen") %>% mutate(policy = pols[gen])
write_csv(diag, here("results/tables/recovery_params.csv"))
cat("\nParameter recovery (generating value, then recovered mean ± SD of the ten best configurations)\n\n| Policy | σ_x generating | σ_x recovered | γ_sample generating | γ_sample recovered | γ_switch generating | γ_switch recovered |\n|---|---|---|---|---|---|---|\n")
for (i in seq_len(nrow(diag))) with(diag[i, ], cat(sprintf("| %s | %.2f | %.2f ± %.2f | %.4f | %.4f ± %.4f | %.3f | %.3f ± %.3f |\n", policy, g_sigma, sigma, sigma_sd, g_gs, gs, gs_sd, g_gw, gw, gw_sd)))
